contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to supply an ERC20 token address and deposit amount. The test will call depositAsset
    // and then assert a general invariant relating getTotalAssetDeposits before/after when call succeeds,
    // and that zero deposits revert.
    function run(address asset, uint256 depositAmount) public payable {
        require(asset != address(0));

        // read before total deposits
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);

        // attempt deposit and record whether it reverted
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.getTotalAssetDeposits(asset);

        // If depositAmount == 0 the contract must revert (InvalidAmount). Otherwise, if it did not revert,
        // then the total deposits reported after must be >= before (no loss of assets) and increased by at most depositAmount + previous (we assert non-decrease and that if succeeded then after >= before)
        // We express: (depositAmount == 0) => reverted; and (!reverted) => afterTotal >= beforeTotal
        assert((depositAmount == 0 ? reverted : true) && (!reverted ? afterTotal >= beforeTotal : true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Adds a list of node delegator addresses and asserts queue length increases by the list length on success.
    function run(address[] calldata nodeDelegators) public payable {
        // require at least one and reasonably small to avoid gas issues in prover
        require(nodeDelegators.length > 0 && nodeDelegators.length <= 20);
        // require none are zero to satisfy UtilLib.checkNonZeroAddress when the call should succeed
        for (uint i = 0; i < nodeDelegators.length; ) {
            require(nodeDelegators[i] != address(0));
            unchecked { ++i; }
        }

        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // General rule: if the call did not revert then the queue length increased by exactly nodeDelegators.length
        assert(reverted || afterLen == beforeLen + nodeDelegators.length);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling transferAssetToNodeDelegator(ndcIndex, asset, amount)
    // either reverts or results in c's total observable holdings for the asset
    // (the sum returned by getAssetDistributionData) decreasing by exactly `amount`.
    function run(address asset, uint256 amount, uint256 ndcIndex) public payable {
        // constrain inputs to reasonable sizes
        require(asset != address(0));
        // limit amount to avoid huge arithmetic
        require(amount <= type(uint128).max);

        // Observe total deposits before the call via public getter
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);

        bool reverted;
        try c.transferAssetToNodeDelegator(ndcIndex, asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.getTotalAssetDeposits(asset);

        // If call reverted, nothing required. If it succeeded, total deposits must have decreased by exactly `amount`.
        // Note: Transfers to a nodeDelegator move tokens out of the deposit pool into NDCs; both are included in getTotalAssetDeposits,
        // so the total should remain the same unless transferFrom semantics differ. However, this contract moves tokens from c to NDC,
        // which are still counted in getTotalAssetDeposits. Therefore the correct invariant is: total deposits do not increase and do not underflow.
        // To be conservative and detect incorrect behavior that burns or mints tokens, we assert that either reverted or afterTotal <= beforeTotal && beforeTotal - afterTotal == amount || afterTotal == beforeTotal.

        assert(reverted || (afterTotal <= beforeTotal && (beforeTotal - afterTotal == amount || afterTotal == beforeTotal)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We supply an array of addresses; the rule: if the call succeeds, the queue length increases by exactly the input length
    // (call either reverts or increases length by input length). To keep things simple we require each address != address(0).
    function run(address[] calldata nodeDelegators) public payable {
        require(nodeDelegators.length <= 20); // bound size for analysis
        // require all addresses non-zero so the call (if it succeeds) should push each one
        for (uint256 i = 0; i < nodeDelegators.length; ++i) {
            require(nodeDelegators[i] != address(0));
        }

        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // General rule: either the call reverted, or the queue length increased by exactly nodeDelegators.length
        assert(reverted || afterLen == beforeLen + nodeDelegators.length);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test updateMaxNodeDelegatorCount(maxCount) : either it reverts or c.maxNodeDelegatorCount() equals maxCount after the call.
    // Bound the input to a moderate value to help verification.
    function run(uint256 maxCount) public payable {
        require(maxCount <= 1000);

        uint256 before = c.maxNodeDelegatorCount();

        bool reverted;
        try c.updateMaxNodeDelegatorCount(maxCount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.maxNodeDelegatorCount();

        // General rule: either the call reverted and state didn't change, or the call succeeded and state equals the requested new maxCount.
        // (If reverted, we require after == before to ensure no partial state change on revert.)
        assert(reverted ? after == before : after == maxCount);
    }

    receive() external payable {}
}
